import numpy as npfrom collections import defaultdictimport cv2track_history = defaultdict(list)def direction(track_id,xmin,ymax,ymin,frame,dict_cars_direction):    track = track_history[track_id]    track.append((float(xmin), float(ymax)))    if len(track) > 30:        track.pop(0)    if len(track) > 3:        if track[-1][0] - track[-2][0]:            dict_cars_direction[track_id].append('->')            cv2.putText(frame, '->', (xmin + 250, ymin), cv2.FONT_HERSHEY_SIMPLEX, 2, (0, 0, 255), 2)        else:            dict_cars_direction[track_id].append('<-')            cv2.putText(frame, '<-', (xmin + 250, ymin), cv2.FONT_HERSHEY_SIMPLEX, 2, (0, 0, 255), 2)    points = np.hstack(track).astype(np.int32).reshape((-1, 1, 2))    cv2.polylines(frame, [points], isClosed=False, color=(230, 230, 230), thickness=10)